INSERT INTO fun_facts (id, fact) VALUES
  (1, 'A group of flamingos is called a "flamboyance."'),
  (2, 'Cleopatra lived closer in time to the Moon landing than to the construction of the Great Pyramid of Giza.'),
  (3, 'Oxford University is older than the Aztec Empire.'),
  (4, 'Wombat poo is cube-shaped — the only known animal to produce cubic feces.'),
  (5, 'A day on Venus is longer than a year on Venus.'),
  (6, 'The shortest war in history was between Britain and Zanzibar in 1896 — it lasted between 38 and 45 minutes.'),
  (7, 'Honey never spoils. Edible honey has been found in 3,000-year-old Egyptian tombs.'),
  (8, 'A bolt of lightning contains enough energy to toast about 100,000 slices of bread.'),
  (9, 'There are more possible iterations of a game of chess than there are atoms in the known universe.'),
  (10, 'Bananas are berries, but strawberries are not.'),
  (11, 'The human nose can detect over 1 trillion different scents.'),
  (12, 'A shrimp''s heart is in its head.'),
  (13, 'Octopuses have three hearts, blue blood, and nine brains (one central and one in each arm).'),
  (14, 'Hot water can freeze faster than cold water under certain conditions. This is known as the Mpemba effect.'),
  (15, 'There are more trees on Earth than stars in the Milky Way galaxy.'),
  (16, 'The average cloud weighs about 1.1 million pounds.'),
  (17, 'Crows can recognize human faces and hold grudges against people who have wronged them.'),
  (18, 'The word "muscle" comes from the Latin word for "little mouse," because Romans thought flexing muscles looked like mice moving under skin.'),
  (19, 'A snail can sleep for up to three years.'),
  (20, 'The total weight of all ants on Earth is roughly equal to the total weight of all humans.'),
  (21, 'Scotland''s national animal is the unicorn.'),
  (22, 'Sharks are older than trees — sharks have existed for about 450 million years, trees for about 350 million.'),
  (23, 'In Switzerland, it''s illegal to own just one guinea pig because they get lonely.'),
  (24, 'The average person walks the equivalent of three times around the Earth in a lifetime.'),
  (25, 'Penguins propose to their mates with pebbles.'),
  (26, 'A group of owls is called a parliament.'),
  (27, 'There are more atoms in a glass of water than glasses of water in all the world''s oceans.'),
  (28, 'The Eiffel Tower grows about 6 inches taller in summer due to thermal expansion.'),
  (29, 'Butterflies taste with their feet.'),
  (30, 'The Hawaiian alphabet has only 13 letters.'),
  (31, 'Polar bear fur is actually transparent, not white — it appears white because it reflects visible light.'),
  (32, 'A blue whale''s heart is so large that a human could swim through its arteries.'),
  (33, 'The inventor of the Frisbee was cremated and turned into a Frisbee after he died.'),
  (34, 'Tigers have striped skin, not just striped fur — the pattern is unique to each individual.'),
  (35, 'If you removed all the empty space from atoms in the human body, all of humanity would fit in a sugar cube.'),
  (36, 'Nintendo was founded in 1889 — originally as a playing card company.'),
  (37, 'The tongue of a blue whale weighs as much as an elephant.'),
  (38, 'The average person will accidentally eat about 430 insects per year while sleeping.'),
  (39, 'Sea otters hold hands while sleeping so they don''t drift apart.'),
  (40, 'Cats can''t taste sweetness — they lack the gene for sweet taste receptors.'),
  (41, 'There are more possible ways to shuffle a deck of cards than there have been seconds since the Big Bang.'),
  (42, 'The Great Wall of China is not visible from space with the naked eye — this is a widespread myth.'),
  (43, 'Cows have best friends and become stressed when separated from them.'),
  (44, 'The inventor of the Pringles can, Fredric Baur, had his ashes buried in one.'),
  (45, 'Babies are born without kneecaps. They develop between ages 2 and 6.'),
  (46, 'A single strand of spaghetti is called a "spaghetto."'),
  (47, 'Elephants are the only animals that can''t jump.'),
  (48, 'The longest place name in the world is in New Zealand: Taumatawhakatangihangakoauauotamateaturipukakapikimaungahoronukupokaiwhenuakitanatahu.'),
  (49, 'Canada has more lakes than the rest of the world combined.'),
  (50, 'Figs contain dead wasps. The fig is actually a flower, and wasps pollinate it by crawling inside.'),
  (51, 'Tomatoes have more genes than humans — 31,760 genes vs. humans'' approximately 20,000–25,000.'),
  (52, 'The footprints on the Moon will last for 100 million years because there''s no wind to erode them.'),
  (53, 'Wolves and ravens have evolved a mutually beneficial friendship — they play together and share food.'),
  (54, 'The average person spends six months of their life waiting for red lights to turn green.'),
  (55, 'The planet Uranus was briefly proposed to be named "Georgium Sidus" after King George III.'),
  (56, 'The human eye can distinguish about 10 million different colors.'),
  (57, 'Iceland has no mosquitoes — it''s one of the few inhabited places on Earth without them.'),
  (58, 'A group of porcupines is called a prickle.'),
  (59, 'Honey bees can recognize human faces using pattern recognition, similar to how we do.'),
  (60, 'Mammoths were still alive when the Great Pyramid was being built.'),
  (61, 'The word "quarantine" comes from the Italian for "forty days," the required isolation period for ships during the plague.'),
  (62, 'A day on Mars is 24 hours, 37 minutes — almost identical to an Earth day.'),
  (63, 'The world''s oldest known living tree is a bristlecone pine named Methuselah, estimated at over 4,800 years old.'),
  (64, 'Squirrels forget where they bury up to 74% of their nuts — accidentally planting thousands of trees each year.'),
  (65, 'The original name for the color orange in English was "yellow-red." The fruit was named first, then the color.'),
  (66, 'Bees can fly higher than Mount Everest.'),
  (67, 'Dolphins have names for each other — they use unique signature whistles to identify individuals.'),
  (68, 'The surface area of Russia is slightly larger than the surface area of Pluto.'),
  (69, 'It takes a photon about 100,000 years to travel from the Sun''s core to its surface, then just 8 minutes to reach Earth.'),
  (70, 'The last letters added to the English alphabet were J and U — in the 16th century.'),
  (71, 'Crows hold "funerals" for their dead, gathering around a deceased crow to learn what killed it.'),
  (72, 'The brain is the only organ that named itself.'),
  (73, 'It rains diamonds on Neptune and Uranus — extreme pressure converts carbon into diamond crystals.'),
  (74, 'An octopus can edit its own RNA to adapt to changing temperatures, essentially rewriting its own genetic instructions.'),
  (75, 'Before GPS, a Mongolian shepherd could navigate by the stars just as accurately as modern technology.'),
  (76, 'Elephants are one of the few animals that recognize themselves in a mirror.'),
  (77, 'The tooth is the only part of the human body that cannot heal itself.'),
  (78, 'Playing video games professionally is a recognized sport in South Korea, with players treated like national celebrities.'),
  (79, 'Flamingos are not naturally pink — they''re born white and turn pink from the carotenoid pigments in their food.'),
  (80, 'The longest hiccups on record lasted 68 years — Charles Osborne hiccupped from 1922 to 1990.'),
  (81, 'Ants never sleep and have no lungs — they breathe through tiny holes in their bodies called spiracles.'),
  (82, 'Statistically, you are more likely to be killed by a champagne cork than by a venomous spider.'),
  (83, 'A group of cats is called a clowder.'),
  (84, 'The unicycle was invented before the bicycle.'),
  (85, 'Lightning strikes the Earth about 100 times per second.'),
  (86, 'The tongue is the strongest muscle in the body relative to its size.'),
  (87, 'If the Sun were the size of a white blood cell, the Milky Way would be the size of the continental United States.'),
  (88, 'There is a species of jellyfish (Turritopsis dohrnii) that is biologically immortal — it can revert to its juvenile form after reaching adulthood.'),
  (89, 'Penguins used to be six feet tall — the extinct species Palaeeudyptes klekowskii was the largest penguin ever discovered.'),
  (90, 'The shortest commercial flight in the world is between two Scottish islands (Westray to Papa Westray) — it lasts about 57 seconds.'),
  (91, 'A group of sharks is called a shiver.'),
  (92, 'Goats have rectangular pupils that allow them to see 320 degrees around them without moving their heads.'),
  (93, 'The blue whale is the loudest animal on Earth — its calls can reach 188 decibels.'),
  (94, 'Mars has the largest volcano in the solar system: Olympus Mons, which is about three times the height of Mount Everest.'),
  (95, 'Every person who has ever spoken the sentence "Let''s get this party started" in a movie theater will have walked in wearing a slightly different expression than they intended.'),
  (96, 'Koalas have fingerprints nearly identical to human fingerprints — even forensic experts have struggled to tell them apart.'),
  (97, 'A day on Mercury lasts twice as long as a year on Mercury.'),
  (98, 'The inventor of the intermittent windshield wiper was refused by car companies, sued them all, and won millions.'),
  (99, 'Cleopatra spoke nine languages. Julius Caesar spoke three.'),
  (100, 'The Great Barrier Reef is the largest living structure on Earth, visible from space.'),
  (101, 'Male seahorses give birth — they carry the eggs in a pouch and go through contractions during delivery.'),
  (102, 'Giraffes have the same number of neck vertebrae as humans — just seven, each up to 10 inches long.'),
  (103, 'The world''s first known author is a woman: Enheduanna, a Sumerian priestess who lived around 2300 BCE.'),
  (104, 'Sloths are so slow that algae actually grows on their fur, giving them a green tint and helpful camouflage.'),
  (105, 'More people have walked on the Moon than have swum to the deepest point of the ocean (the Challenger Deep).'),
  (106, 'Strawberry is an anagram of "sybarwert" — no wait, it isn''t, but "astronomer" is an anagram of "moon starer."'),
  (107, 'The Colosseum in Rome had a retractable roof — a giant awning called the velarium, operated by sailors.'),
  (108, 'Elephants are the only animals besides humans known to perform rituals around death.'),
  (109, 'A group of ravens is called a conspiracy, an unkindness, or a congress.'),
  (110, 'When you look at the night sky, you''re looking into the past — the light from distant stars took millions of years to reach your eyes.'),
  (111, 'The word "nerd" was coined by Dr. Seuss in the 1950 book "If I Ran the Zoo."'),
  (112, 'A horse and a donkey can produce a mule, but mules are almost always sterile.'),
  (113, 'There are more cells in your gut than in the rest of your body combined.'),
  (114, 'The Mona Lisa has no eyebrows — either they were painted and faded, or Da Vinci never added them.'),
  (115, 'Recycling one glass bottle saves enough energy to power a computer for 30 minutes.'),
  (116, 'Otters have a pocket in their skin under each arm where they keep their favorite rocks.'),
  (117, 'Contrary to popular belief, bulls are actually colorblind to red — they react to the movement of the cape, not its color.'),
  (118, 'The average person produces enough saliva in a lifetime to fill two swimming pools.'),
  (119, 'In ancient Rome, urine was used as mouthwash because of the ammonia content.'),
  (120, 'The first email ever sent was by Ray Tomlinson in 1971 — to himself, as a test.'),
  (121, 'Water can boil and freeze at the same time — this phenomenon is called the triple point.'),
  (122, 'A group of pugs is called a grumble.'),
  (123, 'The hashtag symbol (#) is officially called an "octothorpe."'),
  (124, 'Kangaroos can''t walk backwards.'),
  (125, 'There are more possible games of chess than atoms in the observable universe.'),
  (126, 'The smallest country in the world, Vatican City, has its own license plates and phone network.'),
  (127, 'The London Underground''s tunnels are home to a specific species of mosquito — Culex molestus — that evolved separately underground.'),
  (128, 'Shakespeare invented over 1,700 words that are still used in the English language today.'),
  (129, 'The mantis shrimp can punch with the force of a bullet and sees 16 types of color receptors (humans have 3).'),
  (130, 'Humans share approximately 60% of their DNA with bananas.'),
  (131, 'A typical lead pencil can draw a line 35 miles long, or write approximately 45,000 words.'),
  (132, 'The average thunderstorm has about the same energy as an atomic bomb.'),
  (133, 'Every time you shuffle a deck of cards, the order has almost certainly never existed before in human history.'),
  (134, 'Cats brought to Australia by European settlers in the 1700s have now spread across 99.8% of the continent.'),
  (135, 'Lobsters used to be so plentiful they were considered peasant food — fed to prisoners and servants.'),
  (136, 'Pineapples take two years to grow to full size.'),
  (137, 'The acronym LASER stands for "Light Amplification by Stimulated Emission of Radiation."'),
  (138, 'The shortest sentence in English is "Go."'),
  (139, 'Crocodiles can''t stick their tongues out.'),
  (140, 'The moon is slowly drifting away from Earth at a rate of about 3.8 cm per year.'),
  (141, 'Hippo milk is pink.'),
  (142, 'The human body contains enough fat to make seven bars of soap.'),
  (143, 'Only female mosquitoes bite humans — males feed only on flower nectar.'),
  (144, 'A flock of crows is called a murder.'),
  (145, 'The brain uses 20% of the body''s total energy despite being only 2% of its weight.'),
  (146, 'Avocados are toxic to most animals — including cats, dogs, horses, and birds.'),
  (147, 'There are more possible ways for a protein to fold than the age of the universe in nanoseconds.'),
  (148, 'Your stomach gets a new lining every three to four days to prevent it from digesting itself.'),
  (149, 'Ants can carry up to 50 times their own body weight.'),
  (150, 'Ancient Greeks didn''t have a word for the color blue — Homer describes the ocean as "wine-dark" in the Iliad.'),
  (151, 'The world''s first novel is "The Tale of Genji," written by Japanese noblewoman Murasaki Shikibu around 1000 CE.'),
  (152, 'The word "salary" comes from "sal," Latin for salt — Roman soldiers were sometimes paid in salt.'),
  (153, 'Slugs have four noses.'),
  (154, 'Mount Everest grows about 4 millimeters taller each year due to tectonic uplift.'),
  (155, 'Jaguars don''t roar — they make a sound more like a deep, rumbling cough called a "saw."'),
  (156, 'Neptune''s winds are the fastest in the solar system, reaching up to 2,100 km/h.'),
  (157, 'It takes 70% of the world''s fresh water to grow food.'),
  (158, 'Starfish have no brain or blood — they use seawater as a circulatory system.'),
  (159, 'The microwave oven was invented by accident when Percy Spencer noticed radar waves melted a chocolate bar in his pocket.'),
  (160, 'Seahorses are monogamous and mate for life, greeting each other with a daily "dance."'),
  (161, 'Two-thirds of the world''s eggplants are grown in New Jersey.'),
  (162, 'A jiffy is an actual unit of time — 1/100th of a second.'),
  (163, 'The word "muscle" and the word "mouse" share the same Latin root, because Romans saw flexing biceps as mouse-like.'),
  (164, 'There are more bacteria in your mouth than there are people on Earth.'),
  (165, 'Honey badgers are so fearless they''ve been documented waking up mid-attack after being bitten by venomous snakes.'),
  (166, 'The human skeleton renews itself completely approximately every 10 years.'),
  (167, 'In 2004, a Lego brick was found lodged in a man''s lung that had been there for 40 years.'),
  (168, 'Bamboo is the fastest-growing plant on Earth — it can grow nearly 36 inches in a single day.'),
  (169, 'A ball of lightning once rolled through a Russian window and exploded, leaving eyewitnesses completely unharmed.'),
  (170, 'Charles Darwin ate samples of almost every animal he discovered, including owls and armadillos.'),
  (171, 'Pluto is smaller than Russia.'),
  (172, 'Dinosaurs and humans never co-existed — the last non-avian dinosaurs died 66 million years ago, and modern humans appeared about 300,000 years ago.'),
  (173, 'The first car accident in history occurred in Ohio City, Ohio in 1891.'),
  (174, 'The first MP3 ever shared was "Tom''s Diner" by Suzanne Vega, used to test the compression algorithm.'),
